-- Generated by Loom
-- Generator: hub
-- Hash function: sha256
{{ config(materialized='incremental', incremental_strategy='append') }}
SELECT
    customer_hk,
    customer_id,
    __record_source,
    __loaded_at
FROM (
    SELECT
        customer_hk,
        customer_id,
        __record_source,
        __loaded_at,
        ROW_NUMBER() OVER (
            PARTITION BY customer_hk
            ORDER BY __source_ordinal
        ) AS __rn
    FROM (
        SELECT DISTINCT
            LOWER(sha256(UPPER(TRIM(CAST(customer_id AS VARCHAR))))) AS customer_hk,
            UPPER(TRIM(CAST(customer_id AS VARCHAR))) AS customer_id,
            'crm' AS __record_source,
            localtimestamp AS __loaded_at,
            0 AS __source_ordinal
        FROM {{ ref('stg_customers_crm') }}
        WHERE customer_id IS NOT NULL
        UNION ALL
        SELECT DISTINCT
            LOWER(sha256(UPPER(TRIM(CAST(customer_id AS VARCHAR))))) AS customer_hk,
            UPPER(TRIM(CAST(customer_id AS VARCHAR))) AS customer_id,
            'web' AS __record_source,
            localtimestamp AS __loaded_at,
            1 AS __source_ordinal
        FROM {{ ref('stg_customers_web') }}
        WHERE customer_id IS NOT NULL
    ) AS combined
) AS ranked
WHERE __rn = 1
{% if is_incremental() %}
  AND customer_hk NOT IN (
    SELECT target.customer_hk FROM {{ this }} AS target
  )
{% endif %}
